package org.commcare.personalId.profile

import org.commcare.connect.database.ConnectUserDatabaseUtil
import org.commcare.google.services.analytics.AnalyticsParamValue
import org.commcare.google.services.analytics.FirebaseAnalyticsUtil

/**
 * Manage Profile email analytics. Whether the flow adds or changes an email is read from the stored
 * user record, which keeps the old email until verification succeeds, so every report must happen
 * before the new email is stored.
 */
object ProfileEmailAnalytics {
    fun reportInitiated() {
        val action =
            if (isAddingEmail()) {
                AnalyticsParamValue.MANAGE_PROFILE_ACTION_EMAIL_ADD_INITIATED
            } else {
                AnalyticsParamValue.MANAGE_PROFILE_ACTION_EMAIL_UPDATE_INITIATED
            }
        FirebaseAnalyticsUtil.reportPersonalIdProfileAction(action, null)
    }

    /** @param outcome one of the `AnalyticsParamValue.MANAGE_PROFILE_OUTCOME_*` values. */
    fun reportOutcome(outcome: String) {
        val action =
            if (isAddingEmail()) {
                AnalyticsParamValue.MANAGE_PROFILE_ACTION_EMAIL_ADDED
            } else {
                AnalyticsParamValue.MANAGE_PROFILE_ACTION_EMAIL_UPDATED
            }
        FirebaseAnalyticsUtil.reportPersonalIdProfileAction(action, outcome)
    }

    private fun isAddingEmail() = ConnectUserDatabaseUtil.getUser().email.isNullOrEmpty()
}
